import { focusRing } from "@/lib/beton/shared";
import { tv, type VariantProps } from "@/lib/beton/tv";

export const navbar = tv({
  slots: {
    root: "w-full border-b-3 border-border bg-raised",
    inner: "mx-auto flex w-full max-w-7xl items-center gap-6 px-4 sm:px-6",
    brand: [
      "flex shrink-0 items-center gap-2.5 font-display font-black uppercase tracking-tight text-foreground",
      focusRing,
    ],
    nav: "hidden flex-1 items-center gap-1 md:flex",
    link: [
      "flex min-h-11 items-center border-3 border-transparent px-3",
      "font-display font-extrabold uppercase tracking-wide text-foreground",
      "hover:border-border aria-[current=page]:border-border aria-[current=page]:bg-secondary",
      focusRing,
    ],
    actions: "ml-auto flex items-center gap-3",
  },
  variants: {
    size: {
      sm: { inner: "h-14", brand: "text-lg", link: "text-sm" },
      md: { inner: "h-16", brand: "text-2xl", link: "text-sm" },
      lg: { inner: "h-20", brand: "text-3xl", link: "text-base" },
    },
    sticky: {
      true: { root: "sticky top-0 z-40" },
    },
  },
  defaultVariants: {
    size: "md",
    sticky: false,
  },
});

export type NavbarVariants = VariantProps<typeof navbar>;

"use client";

import { navbar, type NavbarVariants } from "@/lib/beton/recipes/navbar.recipe";
import { createContext, useContext, type ComponentProps } from "react";
import { renderElement, type RenderProp } from "@/lib/beton/render-element";

interface NavbarState {
  styles: ReturnType<typeof navbar>;
  size: NonNullable<NavbarVariants["size"]>;
}

const NavbarContext = createContext<NavbarState>({ styles: navbar(), size: "md" });

function useStyles() {
  return useContext(NavbarContext).styles;
}

export interface NavbarProps extends ComponentProps<"header">, NavbarVariants {
  /** Classes for the centred row inside the bar. */
  innerClassName?: string;
  render?: RenderProp;
}

function NavbarRoot({
  size = "md",
  sticky = false,
  className,
  innerClassName,
  children,
  render,
  ...props
}: NavbarProps) {
  const styles = navbar({ size, sticky });
  return (
    <NavbarContext.Provider value={{ styles, size }}>
      {renderElement(
        "header",
        {
          ...props,
          className: styles.root({ class: className }),
          children: <div className={styles.inner({ class: innerClassName })}>{children}</div>,
        },
        render,
      )}
    </NavbarContext.Provider>
  );
}

export interface NavbarBrandProps extends ComponentProps<"a"> {
  render?: RenderProp;
}

function NavbarBrand({ className, href = "/", render, ...props }: NavbarBrandProps) {
  return renderElement(
    "a",
    { ...props, href, className: useStyles().brand({ class: className }) },
    render,
  );
}

export interface NavbarNavProps extends ComponentProps<"nav"> {
  render?: RenderProp;
}

function NavbarNav({
  className,
  "aria-label": ariaLabel = "Main",
  render,
  ...props
}: NavbarNavProps) {
  return renderElement(
    "nav",
    { ...props, "aria-label": ariaLabel, className: useStyles().nav({ class: className }) },
    render,
  );
}

export interface NavbarLinkProps extends ComponentProps<"a"> {
  /** Marks the page you are on. Sets `aria-current="page"`. */
  active?: boolean;
  render?: RenderProp;
}

function NavbarLink({ className, active = false, render, ...props }: NavbarLinkProps) {
  const { styles, size } = useContext(NavbarContext);
  return renderElement(
    "a",
    {
      ...props,
      "aria-current": active ? "page" : undefined,
      "data-size": size,
      className: styles.link({ class: className }),
    },
    render,
  );
}

export interface NavbarActionsProps extends ComponentProps<"div"> {
  render?: RenderProp;
}

function NavbarActions({ className, render, ...props }: NavbarActionsProps) {
  return renderElement(
    "div",
    { ...props, className: useStyles().actions({ class: className }) },
    render,
  );
}

/** The bar across the top of a page: a mark, the main links and a few actions. */
export const Navbar = Object.assign(NavbarRoot, {
  Brand: NavbarBrand,
  Nav: NavbarNav,
  Link: NavbarLink,
  Actions: NavbarActions,
});
